package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.UUID;
import org.bukkit.entity.EntityType;
public class EncounterUpgradeTest {
 @Test public void abyssalGazeOnlyRunsInThirdStageAndHasFiniteLock(){for(var tier:BossCatalog.Tier.values())for(int phase=1;phase<=3;phase++)assertEquals(tier==BossCatalog.Tier.ABYSSAL&&phase==3,AbyssalGaze.available(tier,phase));assertEquals(5000,AbyssalGaze.DURATION);assertEquals(25000,AbyssalGaze.COOLDOWN);assertTrue(AbyssalGaze.CHARGE>=1500);}
 @Test public void virtualSharpnessMatchesJavaAndNeverDoubleCountsWeapons(){assertEquals(5.5,SharpnessRules.missingBonus(0),0);assertEquals(0,SharpnessRules.missingBonus(10),0);assertEquals(.5,SharpnessRules.missingBonus(9),0);assertEquals(0,SharpnessRules.missingBonus(15),0);assertEquals(1,SharpnessRules.bonus(1),0);}
 @Test public void bossDebuffsLastThirtySecondsButPositiveBuffsKeepTheirTimers(){for(String key:new String[]{"poison","wither","mining_fatigue","slowness","weakness","levitation","darkness"})assertEquals(600,BossEffects.duration(key,40));assertEquals(200,BossEffects.duration("blindness",600));assertEquals(200,BossEffects.duration("nausea",600));assertEquals(100,BossEffects.duration("strength",100));assertEquals(100,BossEffects.duration("speed",100));assertTrue(BossEffects.blockedOnBoss("blindness"));assertTrue(BossEffects.blockedOnBoss("nausea"));assertTrue(BossEffects.blockedOnBoss("mining_fatigue"));assertFalse(BossEffects.blockedOnBoss("weakness"));}
 @Test public void limeArrowKeepsThreeArrowheadsAndBoundedStarDetails(){var points=CompassArrow.points(new org.bukkit.util.Vector(0,12,1),20);assertEquals(81,points.size());assertEquals(6,CompassArrow.star().size());for(var point:points){assertEquals(0,point.getY(),0);assertTrue(Double.isFinite(point.length()));assertTrue(point.getZ()>0);}assertEquals(27,CompassArrow.points(new org.bukkit.util.Vector(0,0,1),1).size());assertTrue(CompassArrow.points(new org.bukkit.util.Vector(),10).isEmpty());}
 @Test public void refugeResponseNeedsHitsUnreachablePlayerAndAQuietWindow(){assertTrue(EncounterSafety.challenge(true,true,6000,25000,25000));assertFalse(EncounterSafety.challenge(false,true,6000,25000,0));assertFalse(EncounterSafety.challenge(true,false,6000,25000,0));assertFalse(EncounterSafety.challenge(true,true,2999,25000,0));assertFalse(EncounterSafety.challenge(true,true,6000,24999,25000));}
 @Test public void rareLabelsUseRomanLevelsAndOrangeEquipmentStyle(){assertEquals("V",RareAppearance.roman(5));assertEquals("VIII",RareAppearance.roman(8));assertEquals("XXXV",RareAppearance.roman(35));assertEquals("Forja Viviente (Durability)",RareAppearance.title("durability"));assertTrue(RareAppearance.equipment(org.bukkit.Material.NETHERITE_AXE));assertFalse(RareAppearance.equipment(org.bukkit.Material.MAGMA_CREAM));assertEquals(0xFF9D24,RareAppearance.ORANGE.value());}
 @Test public void burstCooldownIsSharedAndNotResetByPhaseChanges(){var clock=new BurstCadence();clock.initialize(1000);assertFalse(clock.ready(25999));assertTrue(clock.ready(26000));clock.released(27500);clock.initialize(28000);assertEquals(52500,clock.next());assertFalse(clock.ready(52499));assertTrue(clock.ready(52500));}
 @Test public void combatCosmeticsHavePerViewerAndGlobalCeilings(){CosmeticFX.clear();var id=UUID.randomUUID();assertTrue(CosmeticFX.allow(id,384,1000));assertFalse(CosmeticFX.allow(id,1,1000));for(int i=0;i<9;i++)assertTrue(CosmeticFX.allow(UUID.randomUUID(),384,1000));assertFalse(CosmeticFX.allow(UUID.randomUUID(),300,1000));assertTrue(CosmeticFX.allow(id,384,2000));CosmeticFX.clear();}
 @Test public void aquaticMobilityAndEveryMobComboAreBounded(){var old=AquaticCombat.motion(new org.bukkit.util.Vector(1,0,0),false);var enhanced=AquaticCombat.motion(new org.bukkit.util.Vector(1,0,0),false,true);assertEquals(old.length()*1.8,enhanced.length(),.00001);assertTrue(enhanced.length()<.8);for(var boss:BossCatalog.all()){var plan=MobCombos.plan(boss.entityType());assertNotNull(plan);assertNotNull(plan.effect());assertFalse(plan.name().isBlank());assertTrue(MobCombos.damage(100,3)<=120);}}
 @Test public void stageMessageHasReadableBossNameAndBoldDecoration(){var d=BossCatalog.all().iterator().next();var message=StageMessages.format(d,3);assertEquals(net.kyori.adventure.text.format.TextDecoration.State.TRUE,message.decoration(net.kyori.adventure.text.format.TextDecoration.BOLD));assertTrue(net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(message).contains(d.name()));}
 @Test public void shulkerUsesTwentyShotsAndCrossbowPowerTen(){assertEquals(20,ShulkerCombat.VOLLEY_SIZE);assertEquals(25000,ShulkerCombat.BLINK_COOLDOWN);assertEquals(Integer.valueOf(10),PillagerRules.ENCHANTMENTS.get("power"));}
 @Test public void mageProfilesHaveDistinctSpellsWithoutChangingUltimate(){assertTrue(SpellVisuals.mage(EntityType.WITCH));assertTrue(SpellVisuals.mage(EntityType.EVOKER));assertTrue(SpellVisuals.mage(EntityType.ILLUSIONER));assertFalse(SpellVisuals.mage(EntityType.ZOMBIE));assertNotEquals(SpellVisuals.name(1,0),SpellVisuals.name(2,0));for(var boss:BossCatalog.all())if(SpellVisuals.mage(boss.entityType()))assertEquals(SpellVisuals.name(1,0),StageAttackRules.profile(boss,1,0).name());}
}
